def transform(grid):
    """Restore the 1/4 frame and the diagonal periodic field hidden by zeros."""
    rows, cols = len(grid), len(grid[0])
    # Infer the field's period from its visible interior. Values repeat by r+c;
    # choose the smallest period with the greatest agreement to avoid aliases.
    observations = [(r + c, grid[r][c])
                    for r in range(3, rows) for c in range(3, cols)
                    if grid[r][c] != 0]
    best = None
    for period in range(2, 11):
        buckets = defaultdict(Counter)
        for phase, value in observations:
            buckets[phase % period][value] += 1
        correct = sum(max(counts.values()) for counts in buckets.values())
        candidate = (correct, -period, period, buckets)
        if best is None or candidate[:2] > best[:2]:
            best = candidate
    period, buckets = best[2], best[3]
    modes = {phase: counts.most_common(1)[0][0] for phase, counts in buckets.items()}

