 "content": "from collections import Counter, defaultdict


def _row_model(row):
    """Find the shortest strong horizontal color period in a row."""
    best = None
    for period in range(2, 11):
        buckets = defaultdict(Counter)
        for c, value in enumerate(row):
            if value:
                buckets[c % period][value] += 1
        if not buckets:
            continue
        correct = sum(max(counts.values()) for counts in buckets.values())
        total = sum(sum(counts.values()) for counts in buckets.values())
        # Prefer the shortest period among equally well-supported models.
        candidate = (correct / total, correct, -period, period, buckets)
        if best is None or candidate[:3] > best[:3]:
            best = candidate
    if best is None:
        return None
    period, buckets = best[3], best[4]
    return period, {phase: counts.most_common(1)[0][0]
                    for phase, counts in buckets.items()}


def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    models = [_row_model(row) for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                model = models[r]
                if model and c % model[0] in model[1]:
                    out[r][c] = model[1][c % model[0]]
                else:
                    # Fallback to the vertical stripe model from observed values.
                    candidates = [(rr, grid[rr][c]) for rr in range(rows)
                                  if grid[rr][c] != 0]
                    out[r][c] = candidates[0][1] if candidates else 1
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
